using System.Text.Json;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Xunit;

namespace MyApp.Evals.Tests;

public sealed class QualityEvaluationTests : IAsyncLifetime
{
    private const string GoldenPath = "Quality/golden.json";
    private const string RubricPath = "Quality/rubric.md";

    private List<GoldenCase>? _goldenCases;
    private string? _rubric;

    public async Task InitializeAsync()
    {
        var json = await File.ReadAllTextAsync(GoldenPath);
        _goldenCases = JsonSerializer.Deserialize<List<GoldenCase>>(json, new JsonSerializerOptions
        {
            PropertyNameCaseInsensitive = true
        });

        _rubric = await File.ReadAllTextAsync(RubricPath);
    }

    public Task DisposeAsync() => Task.CompletedTask;

    [Fact]
    public void GoldenCasesLoaded()
    {
        Assert.NotNull(_goldenCases);
        Assert.NotEmpty(_goldenCases);
    }

    [Fact]
    public void RubricLoaded()
    {
        Assert.False(string.IsNullOrWhiteSpace(_rubric));
    }

    [Fact]
    public async Task EvaluateGoldenCases()
    {
        Assert.NotNull(_goldenCases);

        foreach (var goldenCase in _goldenCases)
        {
            Assert.False(string.IsNullOrWhiteSpace(goldenCase.Id), "Each golden case must have an id.");
            Assert.False(string.IsNullOrWhiteSpace(goldenCase.UserMessage), "Each golden case must have a user_message.");
            Assert.NotNull(goldenCase.ExpectedTraits);
            Assert.NotEmpty(goldenCase.ExpectedTraits);
        }

        await Task.CompletedTask;
    }
}

public sealed class GoldenCase
{
    public string Id { get; set; } = string.Empty;

    public string UserMessage { get; set; } = string.Empty;

    public List<string> ExpectedTraits { get; set; } = new();
}

